using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the MCP SDK resolves this from the DI container
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool(Name = "get_weather"), Description("Get current weather for a city")]
    public async Task<string> GetWeatherAsync(
        [Description("City name, e.g. 'London'")] string city,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"?q={Uri.EscapeDataString(city)}&appid=demo&units=metric",
            cancellationToken);

        if (response is null)
            return $"No weather data found for '{city}'.";

        return $"{city}: {response.Weather[0].Description}, {response.Main.Temp}°C, humidity {response.Main.Humidity}%";
    }

    [McpServerTool(Name = "get_forecast"), Description("Get 5-day forecast for a city")]
    public async Task<string> GetForecastAsync(
        [Description("City name")] string city,
        [Description("Number of days (1-5)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 5);
        var response = await _httpClient.GetAsync(
            $"/data/2.5/forecast?q={Uri.EscapeDataString(city)}&cnt={days * 8}&appid=demo&units=metric",
            cancellationToken);

        if (!response.IsSuccessStatusCode)
            return $"Failed to get forecast for '{city}': {response.StatusCode}";

        return $"Forecast for {city} ({days} days): retrieved successfully.";
    }
}

